import os
import subprocess
import re
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_COMMANDS = ['status', 'info', 'health', 'version']

def sanitize_hostname(hostname):
    """Basic hostname validation - allows alphanumeric, dots, hyphens"""
    if not hostname:
        return None
    # Allow FQDN-style hostnames
    if re.match(r'^[a-zA-Z0-9][a-zA-Z0-9.\-]{0,253}[a-zA-Z0-9]$', hostname):
        return hostname
    return None

def get_diagnostic_data(target, command):
    """Run network diagnostic against target host"""
    if command not in ALLOWED_COMMANDS:
        return None, "Invalid command"

    # Build the diagnostic command
    # Using ping for 'health', nslookup for 'info', curl for others
    if command == 'health':
        cmd = f"ping -c 1 -W 2 {target}"
    elif command == 'info':
        cmd = f"nslookup {target}"
    elif command == 'status':
        cmd = f"curl -s -o /dev/null -w '%{{http_code}}' http://{target}/status"
    elif command == 'version':
        cmd = f"curl -s http://{target}/version"
    else:
        return None, "Unknown command"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=10
        )
        return result.stdout, None
    except subprocess.TimeoutExpired:
        return None, "Timeout"
    except Exception as e:
        return None, str(e)

@app.route('/api/v1/diagnostic', methods=['POST'])
def run_diagnostic():
    """Endpoint for running network diagnostics on infrastructure targets"""
    data = request.get_json()
    if not data:
        return jsonify({"error": "JSON body required"}), 400

    target = data.get('target', '')
    command = data.get('command', 'health')
    api_key = request.headers.get('X-API-Key', '')

    # Validate API key exists
    if not api_key or len(api_key) < 16:
        return jsonify({"error": "Valid API key required"}), 401

    # Validate command
    if command not in ALLOWED_COMMANDS:
        return jsonify({"error": f"Command must be one of: {ALLOWED_COMMANDS}"}), 400

    # Sanitize the target hostname
    clean_target = sanitize_hostname(target)
    if not clean_target:
        return jsonify({"error": "Invalid hostname format"}), 400

    output, error = get_diagnostic_data(clean_target, command)
    if error:
        return jsonify({"error": error}), 500

    return jsonify({
        "target": clean_target,
        "command": command,
        "result": output
    })

@app.route('/api/v1/batch-diagnostic', methods=['POST'])
def batch_diagnostic():
    """Batch endpoint - accepts semicolon-separated targets for efficiency"""
    data = request.get_json()
    if not data:
        return jsonify({"error": "JSON body required"}), 400

    targets_raw = data.get('targets', '')
    command = data.get('command', 'health')
    api_key = request.headers.get('X-API-Key', '')

    if not api_key or len(api_key) < 16:
        return jsonify({"error": "Valid API key required"}), 401

    if command not in ALLOWED_COMMANDS:
        return jsonify({"error": f"Command must be one of: {ALLOWED_COMMANDS}"}), 400

    # Split targets and process each
    targets = [t.strip() for t in targets_raw.split(';') if t.strip()]
    results = []

    for target in targets:
        clean_target = sanitize_hostname(target)
        if clean_target:
            output, error = get_diagnostic_data(clean_target, command)
            results.append({
                "target": clean_target,
                "result": output,
                "error": error
            })
        else:
            results.append({"target": target, "error": "Invalid hostname"})

    return jsonify({"results": results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
